# Wisbordvragen per deel (alleen in de leerkrachtweergave), hoofdstuk 1 tot 4 van de cursus Krachten 3ASO.
# Uitgevoerd in de naamruimte van aso_krachten.py, na aso_veer.py (die edi, wisbord en VF definieert).
W = wisbord
def drie(start, tijdens, einde):
    return edi([('Start', '<ol>' + ''.join(W(*v) for v in start) + '</ol>'),
                ('Tijdens de uitleg', '<ol>' + ''.join(W(*v) for v in tijdens) + '</ol>'),
                ('Einde', '<ol>' + ''.join(W(*v) for v in einde) + '</ol>')])

